'use strict';
const R=(a,b)=>Math.floor(Math.random()*(b-a+1))+a, P=a=>a[R(0,a.length-1)], F=n=>Number(n).toLocaleString('en-US',{maximumFractionDigits:2}), D=n=>Number(n).toFixed(2), M=n=>'$'+Number(n).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const C=(n,k)=>{let x=1;for(let i=1;i<=k;i++)x=x*(n-i+1)/i;return Math.round(x)}, perm=(n,k)=>{let x=1;for(let i=0;i<k;i++)x*=n-i;return x};
const amort=(p,r,n)=>{let i=r/1200;return p*i/(1-(1+i)**(-n))};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tex=el=>{if(!el)return;const run=()=>{if(window.MathJax?.typesetPromise){window.MathJax.typesetPromise([el]).catch(e=>console.warn('Math rendering:',e));}};if(window.MathJax?.startup?.promise)window.MathJax.startup.promise.then(run).catch(()=>{});else run();};
const sections=[['sets','Sets','Notation, operations, Venn diagrams and surveys'],['counting','Counting','Multiplication principle, permutations, combinations'],['prob','Probability','Events, conditional probability, tables and Bayes'],['stats','Statistics','Data displays, center, spread, correlation and regression'],['units','Units','Conversions, dimensions, rates and percentages'],['finance','Finance','Budgets, inflation, interest, credit and loans']];
// Each generator produces one complete question. A question may have multiple graded parts.
const B={sets:[],counting:[],prob:[],stats:[],units:[],finance:[]};
function add(s,title,make){B[s].push({title,make});}
function q(text,fields,answers,hint,solution,extra={}){return {text,fields,answers,hint,solution,...extra};}
function mc(text,options,answer,why){return q(text,['Choose the best answer'],[answer],'Compare the definitions carefully.',why,{choices:[options]});}
// SETS
add('sets','Set notation and membership',()=>{let a=R(2,6),arr=[a,a+2,a+4,a+6];return mc(`Let A = {${arr.join(', ')}}. Which statement is <strong>true</strong>?`,[`{${a}} ∈ A`,`${a} ∈ A`,`{${a+1}} ⊆ A`,`A has ${arr.length+1} elements`],1,`${a} is an element of A, but the singleton set {${a}} is not listed as an element.`)});
add('sets','Roster and set-builder notation',()=>{let k=R(2,7),n=R(3,6),arr=Array.from({length:n},(_,i)=>(i+1)*k);return mc(`Which set-builder notation describes {${arr.join(', ')}}?`,[`{x | x is a multiple of ${k}}`,`{x | x=${k}n, n=1,2,…,${n}}`,`{x | ${k}≤x≤${n*k}}`,`{x | x>${k}}`],1,`The expression x=${k}n for n=1 through ${n} generates exactly the listed elements.`)});
add('sets','Union, intersection and difference',()=>{let A=[1,2,3,4,5,6].map(x=>x+R(0,0)),B=[3,4,5,7,8],mode=P(['intersection','union','difference']);let res=mode==='intersection'?A.filter(x=>B.includes(x)):mode==='union'?[...new Set([...A,...B])].sort((a,b)=>a-b):A.filter(x=>!B.includes(x));return q(`A={${A}}, B={${B}}. Find A ${mode==='intersection'?'∩':mode==='union'?'∪':'−'} B. Select every element of the result.`,['Elements'],[res],'Use the definition of '+mode+'.',`The result is {${res.join(', ')}}.`,{multiSelect:{options:[1,2,3,4,5,6,7,8],correct:res}})});
add('sets','Three-set Venn region',()=>{let masks=[1,2,3,4,5,6,7],target=P([1,2,3,4,5,6,7]),lab=['A only','B only','A ∩ B only','C only','A ∩ C only','B ∩ C only','A ∩ B ∩ C'];return q(`Shade the region <strong>${lab[masks.indexOf(target)]}</strong> on the interactive Venn diagram. Click the region to toggle shading.`,['Shaded region'],[target],'Only the requested part of the diagram should be selected.',`Shade ${lab[masks.indexOf(target)]} and no other regions.`,{diagram:{type:'venn',correct:[target]}})});
add('sets','Survey: inclusion-exclusion',()=>{let both=R(5,14),onlyA=R(12,27),onlyB=R(9,24),neither=R(4,15),total=both+onlyA+onlyB+neither;return q(`Among ${total} students, ${onlyA+both} use the library, ${onlyB+both} use the tutoring center, and ${both} use both. How many use at least one? How many use neither?`,['At least one','Neither'],[onlyA+onlyB+both,neither],'Add the two totals and subtract the overlap once.',`${onlyA+both}+${onlyB+both}−${both}=${onlyA+onlyB+both}; neither=${total}−${onlyA+onlyB+both}=${neither}.`)});
add('sets','Three-way survey reasoning',()=>{let t=R(2,7),ab=R(3,7),ac=R(2,6),bc=R(2,6),a=R(8,15),b=R(8,15),c=R(8,15),none=R(5,15),N=t+ab+ac+bc+a+b+c+none;return q(`A survey of ${N} people asks about three activities A, B and C. Exactly A: ${a}; exactly B: ${b}; exactly C: ${c}; exactly A and B: ${ab}; exactly A and C: ${ac}; exactly B and C: ${bc}; all three: ${t}. Find the number doing <strong>exactly two</strong> and <strong>none</strong>.`,['Exactly two','None'],[ab+ac+bc,none],'“Exactly two” excludes the triple intersection.',`Exactly two=${ab}+${ac}+${bc}=${ab+ac+bc}; none=${N}−${N-none}=${none}.`)});
add('sets','Complement and De Morgan',()=>{let which=P([0,1]);return mc(`Which identity is correct for sets A and B?`,which?['(A ∩ B)′ = A′ ∩ B′','(A ∩ B)′ = A′ ∪ B′','(A ∩ B)′ = A ∪ B','(A ∩ B)′ = A ∩ B']:['(A ∪ B)′ = A′ ∪ B′','(A ∪ B)′ = A ∩ B','(A ∪ B)′ = A′ ∩ B′','(A ∪ B)′ = A ∪ B'],which?1:2,'De Morgan’s laws interchange union and intersection when taking complements.');});
// COUNTING
add('counting','Fundamental counting principle',()=>{let x=R(3,8),y=R(2,6),z=R(2,5),context=P(['outfits','meal combinations','travel packages']);return q(`A store offers ${x} choices of a first item, ${y} of a second, and ${z} of a third to make ${context}. How many distinct combinations are possible?`,['Total combinations'],[x*y*z],'Multiply the number of choices at each independent stage.',`${x}×${y}×${z}=${x*y*z}.`)});
add('counting','Permutations or combinations?',()=>{let n=R(7,12),k=R(2,4),roles=P([true,false]),text=roles?`A club with ${n} members selects ${k} different officers with distinct positions.`:`A club with ${n} members selects a ${k}-person committee with no assigned roles.`;return q(`${text} How many selections are possible?`,['Number of selections'],[roles?perm(n,k):C(n,k)],'Ask whether changing the order produces a different outcome.',roles?`Order matters: ${n}P${k}=${perm(n,k)}.`:`Order does not matter: ${n}C${k}=${C(n,k)}.`)});
add('counting','Teams with restrictions',()=>{let n=R(9,13),k=R(3,5),bad=C(n-2,k-2);return q(`From ${n} volunteers, form a team of ${k}. Two particular volunteers refuse to serve together. How many valid teams can be formed?`,['Valid teams'],[C(n,k)-bad],'Subtract teams containing both restricted volunteers.',`All teams: ${C(n,k)}. Teams with both: ${C(n-2,k-2)}. Valid: ${C(n,k)-bad}.`)});
add('counting','Committees with categories',()=>{let a=R(5,9),b=R(5,9),x=R(2,3),y=R(1,3);return q(`There are ${a} first-year and ${b} upper-year students. How many committees have exactly ${x} first-year and ${y} upper-year members?`,['Number of committees'],[C(a,x)*C(b,y)],'Choose independently from the two groups, then multiply.',`${a}C${x} × ${b}C${y} = ${C(a,x)*C(b,y)}.`)});
add('counting','License plates and repetition',()=>{let letters=R(2,4),digits=R(2,4),distinct=P([true,false]),v=(distinct?perm(26,letters):26**letters)*10**digits;return q(`A code has ${letters} letters followed by ${digits} digits. ${distinct?'Letters cannot repeat':'Letters may repeat'}, and digits may repeat. How many codes are possible?`,['Number of codes'],[v],'Count choices for each position; repetition rules apply separately to letters and digits.',`Letters: ${distinct?perm(26,letters):26**letters}; digits: 10^${digits}=${10**digits}. Total=${v}.`)});
add('counting','Counting method recognition',()=>{let c=P([0,1,2]);let options=['Multiply the choices','Use a permutation','Use a combination','Add the choices'];return mc([`A customer chooses one drink, one sandwich and one side. Which method is appropriate?`,`A contest awards first, second and third places to different participants. Which method is appropriate?`,`A researcher selects five people for an unordered focus group. Which method is appropriate?`][c],options,c,`The correct method is ${options[c].toLowerCase()}.`)});
add('counting','At least one condition',()=>{let n=R(7,11),k=R(2,4),special=R(2,3);return q(`A committee of ${k} is selected from ${n} people, including ${special} experienced members. How many committees include at least one experienced member?`,['Committees'],[C(n,k)-C(n-special,k)],'Count all committees and subtract those with no experienced members.',`${C(n,k)}−${C(n-special,k)}=${C(n,k)-C(n-special,k)}.`)});
// PROBABILITY
add('prob','Complement and simple events',()=>{let n=R(12,30),a=R(3,n-3);return q(`A bag contains ${a} blue tokens and ${n-a} other tokens. A token is drawn at random. What is P(not blue)?`,['Probability'],[(n-a)/n],'Use the complement rule: P(not A)=1−P(A).',`P(not blue)=${n-a}/${n}=${D((n-a)/n)}.`)});
add('prob','Independent or mutually exclusive?',()=>{let kind=P([0,1,2]);return mc([`A fair die is rolled. A={even}, B={greater than 3}. How are A and B related?`,`A card is drawn. A={heart}, B={spade}. How are A and B related?`,`A coin is tossed twice. A={first toss heads}, B={second toss heads}. How are A and B related?`][kind],['Mutually exclusive only','Independent only','Both','Neither'],[3,0,1][kind],['The events overlap but their probabilities do not multiply to their intersection.','A single card cannot be both a heart and a spade.','Separate fair coin tosses are independent.'][kind]);});
add('prob','Two draws without replacement',()=>{let red=R(4,9),blue=R(3,8);return q(`A bag contains ${red} red and ${blue} blue balls. Two are drawn without replacement. Find P(both red).`,['Probability'],[(red/(red+blue))*((red-1)/(red+blue-1))],'The second draw has one fewer red ball and one fewer ball overall.',`(${red}/${red+blue})(${red-1}/${red+blue-1})=${D(red/(red+blue)*(red-1)/(red+blue-1))}.`)});
add('prob','Two-way table and conditional probability',()=>{let a=R(12,32),b=R(8,24),c=R(14,30),d=R(10,27);return q(`<table class="data-table"><tr><th></th><th>Car</th><th>Transit</th></tr><tr><th>On campus</th><td>${a}</td><td>${b}</td></tr><tr><th>Off campus</th><td>${c}</td><td>${d}</td></tr></table>Find P(transit | on campus) and P(off campus or car).`,['Conditional probability','Union probability'],[b/(a+b),(c+d+a+c-c)/(a+b+c+d)],'For conditional probability, restrict the denominator to the given row. For “or”, add and subtract the overlap.',`P(transit|on)=${b}/${a+b}. P(off or car)=(${c+d}+${a+c}−${c})/${a+b+c+d}.`)});
add('prob','Law of total probability',()=>{let p=P([.2,.25,.3,.4]),a=P([.06,.08,.1,.12]),b=P([.01,.02,.03,.04]);return q(`${p*100}% of drivers belong to group D. The accident probability is ${a*100}% for D and ${b*100}% for non-D. Find the probability a randomly selected driver has an accident.`,['Overall probability'],[p*a+(1-p)*b],'Use P(A)=P(A|D)P(D)+P(A|not D)P(not D).',`${p}(${a})+${1-p}(${b})=${D(p*a+(1-p)*b)}.`)});
add('prob','Bayes theorem',()=>{let p=P([.2,.3,.4]),a=P([.1,.15,.2]),b=P([.02,.04,.05]);let total=p*a+(1-p)*b;return q(`A medical screening program has ${p*100}% high-risk participants. A positive result occurs in ${a*100}% of high-risk participants and ${b*100}% of other participants. If a result is positive, what is P(high-risk | positive)?`,['Conditional probability'],[p*a/total],'Use Bayes: numerator is P(positive | high-risk)P(high-risk); denominator is overall positive probability.',`(${p}×${a})/[${p}×${a}+${1-p}×${b}]=${D(p*a/total)}.`)});
add('prob','Probability using combinations',()=>{let a=R(5,8),b=R(5,8),k=4,x=2;return q(`A random ${k}-person team is chosen from ${a} first-year and ${b} upper-year students. What is the probability exactly ${x} are first-year?`,['Probability'],[C(a,x)*C(b,k-x)/C(a+b,k)],'Favorable combinations divided by all combinations.',`(${C(a,x)}×${C(b,k-x)})/${C(a+b,k)}=${D(C(a,x)*C(b,k-x)/C(a+b,k))}.`)});
// STATS
add('stats','Population, sample and statistic',()=>{let n=R(80,350),avg=R(8,20);return mc(`A researcher surveys ${n} randomly selected students at a university and finds a mean study time of ${avg} hours. What is the <strong>sample</strong>?`,['All university students',`The ${n} surveyed students`,`${avg} hours`,'All students in the country'],1,`The sample consists of the ${n} individuals actually surveyed.`)});
add('stats','Variable type and graph choice',()=>{let c=P([0,1,2]);return mc([`Which graph is best for the distribution of ${R(80,200)} numerical exam scores?`,`Which graph is best for showing proportions of students by favorite sport?`,`Which graph best shows the relationship between hours studied and exam score?`][c],['Pie chart','Histogram','Scatterplot','Line chart of categories'],[1,0,2][c],['Numerical distributions use histograms.','Categories and shares can be displayed with a pie chart.','Paired quantitative variables use a scatterplot.'][c]);});
add('stats','Mean, median and outliers',()=>{let x=R(6,12),vals=[x,x+2,x+3,x+4,x+6],out=P([false,true]);if(out)vals[4]=x+R(20,35);let mean=vals.reduce((a,b)=>a+b)/5;return q(`For the data ${vals.join(', ')}, find the mean and median. ${out?'Explain conceptually why the mean is more affected by the largest value.':''}`,['Mean','Median'],[mean,vals[2]],'Add all values and divide by five; the median is the middle sorted value.',`Mean=(${vals.join('+')})/5=${D(mean)}; median=${vals[2]}. ${out?'The unusually high value pulls the mean upward.':''}`)});
add('stats','Variance and standard deviation',()=>{let base=R(4,18),step=R(2,6),vals=[base,base+step,base+2*step,base+3*step,base+4*step],mean=base+2*step,sumsq=10*step*step;let variance=sumsq/4;return q(`Data: ${vals.join(', ')}. Calculate the <strong>sample</strong> variance and standard deviation.`,['Variance','Standard deviation'],[variance,Math.sqrt(variance)],`Mean=${mean}. Compute squared deviations and divide by n−1.`,`Sum of squared deviations=${sumsq}. Variance=${sumsq}/4=${D(variance)}; standard deviation=${D(Math.sqrt(variance))}.`)});
add('stats','Build a histogram',()=>{let freq=Array.from({length:4},()=>R(2,9)),labels=['[0,10)','[10,20)','[20,30)','[30,40)'];return q(`Construct a <strong>histogram</strong> for the grouped frequency table below. Click +/− to set the height of each bar. <table class="data-table"><tr><th>Interval</th>${labels.map(v=>`<th>${v}</th>`).join('')}</tr><tr><th>Frequency</th>${freq.map(v=>`<td>${v}</td>`).join('')}</tr></table>`,['Bar heights'],[...freq],'Adjacent bars represent consecutive numeric intervals; each bar height is its frequency.',`The bar heights from left to right are ${freq.join(', ')}.`,{diagram:{type:'bars',kind:'histogram',labels,correct:freq,max:12}})});
add('stats','Build a bar chart',()=>{let cats=P([['Gym','Run','Swim','Cycle'],['Bus','Car','Walk','Bike'],['Tea','Coffee','Water','Juice']]),freq=Array.from({length:4},()=>R(2,9));return q(`Construct a <strong>bar chart</strong> for these categories by setting the bar heights: <table class="data-table"><tr><th>Category</th>${cats.map(v=>`<th>${v}</th>`).join('')}</tr><tr><th>Frequency</th>${freq.map(v=>`<td>${v}</td>`).join('')}</tr></table>`,['Bar heights'],freq,'Bars for categorical data have gaps; their heights are frequencies.',`The heights for ${cats.join(', ')} are ${freq.join(', ')}.`,{diagram:{type:'bars',kind:'bar',labels:cats,correct:freq,max:12}})});
add('stats','Construct a pie chart',()=>{let cats=P([['Gym','Running','Cycling','Swimming'],['Rent','Food','Travel','Other'],['A','B','C','D']]),v=[R(2,5),R(2,5),R(2,5),R(2,5)],tot=v.reduce((a,b)=>a+b);let pct=v.map(x=>100*x/tot);return q(`A survey recorded these category frequencies. Adjust each sector's <strong>percentage</strong> to create the pie chart. <table class="data-table"><tr><th>Category</th>${cats.map(x=>`<th>${x}</th>`).join('')}</tr><tr><th>Count</th>${v.map(x=>`<td>${x}</td>`).join('')}</tr></table>`,['Sector percentages'],pct,'Each sector percentage is 100 × frequency ÷ total.',`Total=${tot}. Percentages are ${pct.map(D).join('%, ')}%.`,{diagram:{type:'pie',labels:cats,correct:pct}})});
add('stats','Plot a scatter diagram',()=>{let slope=P([1,-1]),points=Array.from({length:5},(_,i)=>[i+1,slope===1?i+R(1,2)+2:9-i-R(0,1)]);return q(`Plot these five ordered pairs on the <strong>scatter diagram</strong> by clicking the grid intersections: ${points.map(v=>`(${v[0]},${v[1]})`).join(', ')}. Click a selected point again to remove it.`,['Plotted points'],[points.length],'The horizontal coordinate is x and the vertical coordinate is y.',`Plot exactly the five points: ${points.map(v=>`(${v.join(',')})`).join(', ')}.`,{diagram:{type:'scatter',correct:points}})});
add('stats','Correlation and regression',()=>{let xbar=R(3,8),ybar=R(45,80),vx=R(3,9),vy=R(25,75),r=P([.6,.7,.8,-.6,-.7,-.8]),cov=r*Math.sqrt(vx*vy),slope=cov/vx,b=ybar-slope*xbar,x=R(1,10);return q(`A study reports x̄=${xbar}, ȳ=${ybar}, Var(x)=${vx}, Var(y)=${vy}, Cov(x,y)=${D(cov)} (use the unrounded covariance implied by r=${r}). Find the regression slope and the predicted y-value at x=${x}.`,['Regression slope','Predicted y'],[slope,slope*x+b],'Slope = covariance / variance of x; intercept = ȳ−slope·x̄.',`Slope=${D(cov)}/${vx}≈${D(slope)}; intercept=${D(b)}; prediction=${D(slope*x+b)}.`)});
add('stats','Interpreting correlation',()=>{let r=P([-.91,-.75,-.38,.25,.61,.88]);return mc(`A study finds correlation r=${r}. Which description is most appropriate?`,['Strong positive linear relationship','Strong negative linear relationship','Weak-to-moderate positive linear relationship','Weak-to-moderate negative linear relationship'],r>=.7?0:r<=-.7?1:r>0?2:3,`The sign gives direction and |r|=${Math.abs(r)} indicates the strength of the linear association.`)});
add('stats','Sampling bias and misleading displays',()=>{let scenario=P([0,1]);return mc(scenario?'A graph of favorite music genres connects categories with a continuous line. What is the main problem?':'To estimate campus exercise habits, a student surveys only people leaving the gym. What is the main concern?',scenario?['The graph has too few points','The line implies a continuous relationship between categories','The graph must always be a histogram','A larger y-axis is needed']:['The sample is biased toward students who exercise','The sample mean is always zero','The study is an experiment','The data must be categorical'],scenario?1:0,scenario?'A line connecting unordered categories can falsely suggest continuity.':'Gym users are not representative of all university students.');});
// UNITS
add('units','Temperature conversion',()=>{let f=P([true,false]),n=R(-12,98);return q(`A ${P(['weather station','laboratory','kitchen','travel report'])} records ${n}°${f?'F':'C'}. Convert to °${f?'C':'F'}.`,['Converted temperature'],[f?(n-32)*5/9:n*9/5+32],f?'C=(F−32)×5/9.':'F=9C/5+32.',f?`(${n}−32)×5/9=${D((n-32)*5/9)}°C.`:`9(${n})/5+32=${D(n*9/5+32)}°F.`)});
add('units','Speed conversion',()=>{let mph=P([true,false]),speed=R(25,85),factor=1.609344;return q(`A ${P(['cyclist','driver','runner','delivery vehicle'])} travels at ${speed} ${mph?'mph':'km/h'}. Convert to ${mph?'km/h':'mph'}.`,['Converted speed'],[mph?speed*factor:speed/factor],'1 mile = 1.609344 kilometers.',`${speed} ${mph?'×':'÷'} 1.609344 = ${D(mph?speed*factor:speed/factor)}.`)});
add('units','Area and volume conversion',()=>{let volume=P([true,false]),x=R(3,12),y=R(4,13),z=R(2,8);return q(volume?`A box measures ${x} in × ${y} in × ${z} in. Find its volume in liters (1 in=2.54 cm; 1000 cm³=1 L).`:`A rectangular floor measures ${x} ft × ${y} ft. Find its area in square inches.`,['Converted measurement'],[volume?x*y*z*2.54**3/1000:x*y*144],volume?'Multiply three dimensions and cube the length conversion.':'Square the length conversion factor.',volume?`Volume=${x*y*z} in³ × (2.54)³/1000 = ${D(x*y*z*2.54**3/1000)} L.`:`Area=${x*y} ft² ×144=${x*y*144} in².`)});
add('units','Dimensional analysis and weight',()=>{let kg=P([true,false]),x=R(20,120);return q(`A ${P(['package','person','piece of equipment','shipment'])} has a mass of ${x} ${kg?'kg':'lb'}. Convert to ${kg?'lb':'kg'} using 1 kg = 2.20462 lb.`,['Converted amount'],[kg?x*2.20462:x/2.20462],'Set up the conversion factor so the original units cancel.',`${x} ${kg?'×':'÷'}2.20462 = ${D(kg?x*2.20462:x/2.20462)}.`)});
add('units','Compare unit prices',()=>{let a=R(8,20),b=R(6,17),qa=R(2,5),qb=R(2,5);return q(`Store A sells ${qa} kg of rice for ${M(a)}. Store B sells ${qb} kg for ${M(b)}. Find the two unit prices per kilogram.`,['Store A ($/kg)','Store B ($/kg)'],[a/qa,b/qb],'Divide each total price by its kilograms.',`A=${M(a/qa)}/kg; B=${M(b/qb)}/kg. ${a/qa<b/qb?'A':a/qa>b/qb?'B':'Both'} is cheaper.`)});
add('units','Currency exchange and surface pricing',()=>{let rate=P([1.25,1.32,1.4,1.47]),price=R(20,90);return q(`An item costs ${price} Canadian dollars. The exchange rate is 1 USD = ${rate} CAD. Find the cost in USD.`,['USD cost'],[price/rate],'Divide Canadian dollars by CAD per USD.',`${price}÷${rate}=${M(price/rate)}.`)});
add('units','Reverse percentages and tax',()=>{let original=R(40,180),tax=R(5,10),tip=R(12,22),total=original*(1+(tax+tip)/100);return q(`A restaurant bill is ${M(total)} after a ${tax}% tax and a ${tip}% tip, each calculated on the original menu price. Find the original price.`,['Original price'],[original],'Both percentages use the same original base.',`${M(total)}÷(1+${tax}/100+${tip}/100)=${M(original)}.`)});
// FINANCE
add('finance','Monthly budget and savings rate',()=>{let wage=R(13,26),hours=R(15,35),expenses=R(600,1100),income=wage*hours*4;return q(`A student earns ${M(wage)}/hour and works ${hours} hours/week, four weeks/month. Monthly expenses are ${M(expenses)}. Find monthly savings and the percentage of income saved.`,['Monthly savings ($)','Savings (%)'],[income-expenses,100*(income-expenses)/income],'Monthly income = hourly pay × hours × 4. Savings = income − expenses.',`Income=${M(income)}; savings=${M(income-expenses)}; savings rate=${D(100*(income-expenses)/income)}%.`)});
add('finance','Inflation over multiple years',()=>{let price=R(6,24)+.99,rates=[R(2,6),R(2,6),R(2,6)],final=rates.reduce((v,r)=>v*(1+r/100),price);return q(`An item costs ${M(price)}. Its price increases by ${rates[0]}%, ${rates[1]}%, and ${rates[2]}% over the next three years. Find the final price.`,['Final price ($)'],[final],'Apply each annual percentage to the newly updated price.',`${M(price)}×${rates.map(r=>`(1+${r}/100)`).join('×')}=${M(final)}.`)});
add('finance','Simple interest and maturity',()=>{let principal=R(20,90)*100,rate=R(3,9)/10,months=R(6,30);let amount=principal*(1+rate/100*months/12);return q(`A certificate of deposit of ${M(principal)} earns ${rate}% annual <strong>simple interest</strong> for ${months} months. Find the maturity value.`,['Maturity value ($)'],[amount],'A=P(1+rt) with time measured in years.',`A=${principal}(1+${rate}/100×${months}/12)=${M(amount)}.`)});
add('finance','Compound growth',()=>{let p=R(20,90)*100,r=R(3,9),t=R(2,7),n=P([1,4,12,365]),a=p*(1+r/100/n)**(n*t);return q(`${M(p)} is invested at ${r}% annual interest compounded ${n===1?'annually':n===4?'quarterly':n===12?'monthly':'daily'} for ${t} years. Find the final balance.`,['Final balance ($)'],[a],'Use A=P(1+r/n)^(nt) with r as a decimal.',`A=${p}(1+${r}/(100×${n}))^(${n}×${t})=${M(a)}.`)});
add('finance','Amortized loan payments',()=>{let p=R(7,24)*1000,r=R(4,12),years=R(2,6),a=amort(p,r,years*12);return q(`A ${P(['car','renovation','personal'])} loan of ${M(p)} has an annual interest rate of ${r}% with fixed monthly payments over ${years} years. Find the monthly payment.`,['Monthly payment ($)'],[a],'Monthly rate i=r/1200 and N=12×years. M=Pi/[1−(1+i)^−N].',`M=${M(p)}×(${r}/1200)/[1−(1+${r}/1200)^−${years*12}]=${M(a)}.`)});
add('finance','Mortgage and down payment',()=>{let house=R(20,55)*10000,down=R(10,25),r=R(4,8)+.5,years=P([15,20,25,30]),p=house*(1-down/100),pay=amort(p,r,years*12);return q(`A house costs ${M(house)}. The buyer puts ${down}% down and finances the remainder at ${r}% annual interest over ${years} years. Find the monthly mortgage payment and total amount paid including the down payment.`,['Monthly payment ($)','Total paid ($)'],[pay,pay*years*12+house*down/100],'Subtract the down payment before using the amortization formula.',`Loan=${M(p)}; payment=${M(pay)}; total=${M(pay*years*12+house*down/100)}.`)});
add('finance','Credit card minimum payment',()=>{let balance=R(8,35)*100,apr=R(18,30),min=R(3,8),charged=balance*(1+apr/1200),paid=charged*min/100;return q(`A credit card balance is ${M(balance)}, APR ${apr}%. The bank adds one month of interest, then requires a minimum payment of ${min}% of the new balance. Find the payment and remaining balance.`,['Minimum payment ($)','Balance after payment ($)'],[paid,charged-paid],'Interest is added before calculating the percentage payment.',`Balance after interest=${M(charged)}; payment=${M(paid)}; remaining=${M(charged-paid)}.`)});
add('finance','Conceptual loan types',()=>{let which=P([0,1,2]);return mc([`A student loan accrues no interest while the borrower remains in school. Which is the best description?`,`A loan accrues interest while the student is enrolled, with repayment beginning after graduation. Which is it?`,`A loan is repaid by fixed payments that reduce principal over time. Which is it?`][which],['Subsidized student loan','Unsubsidized student loan','Amortized loan','Simple-interest savings account'],which,'Identify when interest accrues and whether payments reduce the outstanding balance.');});
add('finance','Retirement annuity',()=>{let weekly=R(20,90),r=R(3,8),years=R(4,15),i=r/100/52,N=52*years,a=weekly*((1+i)**N-1)/i;return q(`An employee deposits ${M(weekly)} each week into a retirement account earning ${r}% annually, compounded weekly. Find the future value after ${years} years (end-of-week deposits).`,['Future value ($)'],[a],'Future value of an ordinary annuity: D[(1+i)^N−1]/i.',`i=${r}/(100×52), N=${N}. Future value=${M(a)}.`)});

// REVISION: expanded generators. Mathematical regions are encoded by membership bits A=1,B=2,C=4.
const math=t=>`\\(${t}\\)`, setfmt=a=>`\\{${a.join(', ')}\\}`;
const sum=a=>a.reduce((x,y)=>x+y,0), avg=a=>sum(a)/a.length;
const variance=(a,sample=true)=>sum(a.map(x=>(x-avg(a))**2))/(a.length-(sample?1:0));
const sd=(a,sample=true)=>Math.sqrt(variance(a,sample));
const covar=(a,b)=>sum(a.map((x,i)=>(x-avg(a))*(b[i]-avg(b))))/(a.length-1);
const table=(headers,rows)=>`<table class="data-table"><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
const shuffle=a=>{let b=[...a];for(let i=b.length-1;i>0;i--){let j=R(0,i);[b[i],b[j]]=[b[j],b[i]];}return b;};
const choose=(n,k)=>`C(${n},${k})=\\frac{${n}!}{${k}!(${n}-${k})!}=${C(n,k)}`;
function replace(s,title,make){let i=B[s].findIndex(x=>x.title===title);if(i>=0)B[s][i].make=make;else add(s,title,make);}
// SETS: varying universe, contexts, operation trees, region targets.
replace('sets','Union, intersection and difference',()=>{let n=R(10,17),U=Array.from({length:n},(_,i)=>i+1),A=U.filter(()=>Math.random()<.56),B=U.filter(()=>Math.random()<.55),Cset=U.filter(()=>Math.random()<.45);let ops=[['A\\cap B',x=>A.includes(x)&&B.includes(x)],['A\\cup B',x=>A.includes(x)||B.includes(x)],['A-B',x=>A.includes(x)&&!B.includes(x)],['A^{c}',x=>!A.includes(x)],['(A\\cup B)^{c}',x=>!A.includes(x)&&!B.includes(x)],['A\\cap B^{c}',x=>A.includes(x)&&!B.includes(x)],['(A\\cup B)-C',x=>(A.includes(x)||B.includes(x))&&!Cset.includes(x)],['(A\\cap B)\\cup C^{c}',x=>(A.includes(x)&&B.includes(x))||!Cset.includes(x)],['(A-B)\\cup C',x=>(A.includes(x)&&!B.includes(x))||Cset.includes(x)]];let [expression,test]=P(ops),result=U.filter(test);return q(`Let the universal set be ${math('U='+setfmt(U))}.<p>${math('A='+setfmt(A))}, ${math('B='+setfmt(B))}, ${math('C='+setfmt(Cset))}.</p><p>Select every element of ${math(expression)}.</p>`,['Elements'],[result],`Work inside U. Apply complements relative to U, then intersections or differences, and finally unions as indicated.`,`<p>Universe: ${math('U='+setfmt(U))}.</p><p>Evaluate ${math(expression)} one operation at a time. The resulting set is ${math(setfmt(result))}.</p>`,{multiSelect:{options:U,correct:result}});});
replace('sets','Three-set Venn region',()=>{let expressions=[['A\\cup B',m=>(m&3)!==0],['A\\cap B',m=>(m&3)===3],['(A\\cup B)-C',m=>(m&3)!==0&&!(m&4)],['A-(B\\cup C)',m=>m===1],['(A\\cap C)\\cup B',m=>(m&5)===5||(m&2)!==0],['(A\\cup B\\cup C)^c',m=>m===0],['A^c\\cap B^c',m=>!(m&1)&&!(m&2)],['(A\\cap B)^c',m=>(m&3)!==3],['(A\\cup C)\\cap B^c',m=>((m&5)!==0)&&!(m&2)],['(A-B)\\cup(C-A)',m=>((m&1)&&!(m&2))||((m&4)&&!(m&1))],['U-(A\\cap C)',m=>(m&5)!==5],['(A\\cup B)\\cap C',m=>(m&3)!==0&&(m&4)!==0]];let [expression,predicate]=P(expressions),correct=Array.from({length:8},(_,i)=>i).filter(i=>predicate(i===7?0:[1,2,3,4,5,6,7][i])); // map region 8 to exterior
return q(`Shade <strong>all and only</strong> the regions belonging to ${math(expression)}. The rectangle is the universe ${math('U')}; <strong>Region 8</strong> is outside all three circles.`,['Regions'],[correct],`Translate each region into its memberships in A, B and C; complement means everything outside the indicated set, including the exterior when appropriate.`,`<p>For ${math(expression)}, select regions <strong>${correct.map(x=>x+1).join(', ')}</strong>.</p><p>Regions 1–7 represent the seven interior combinations; region 8 is ${math('(A\\cup B\\cup C)^c')}.</p>`,{diagram:{type:'venn',correct:correct.map(x=>x+1)}});});
replace('sets','Three-way survey reasoning',()=>{let names=P([['Basketball','Swimming','Tennis'],['Reading','Hiking','Gaming'],['Music','Art','Drama'],['Bus','Bike','Carpool'],['Biology','Chemistry','Physics']]);let counts=Array.from({length:8},(_,i)=>R(i===0?5:3,i===0?14:16)),N=sum(counts);let labels=['None','Only '+names[0],'Only '+names[1],names[0]+' and '+names[1]+' only','Only '+names[2],names[0]+' and '+names[2]+' only',names[1]+' and '+names[2]+' only','All three'];let targets=[['exactly one',counts[1]+counts[2]+counts[4]],['exactly two',counts[3]+counts[5]+counts[6]],['at least one',N-counts[0]],['none',counts[0]],['all three',counts[7]],['only '+names[0],counts[1]],['only '+names[1],counts[2]],['only '+names[2],counts[4]],['both '+names[0]+' and '+names[1]+' (possibly also '+names[2]+')',counts[3]+counts[7]],['at least two',counts[3]+counts[5]+counts[6]+counts[7]],['not '+names[0],counts[0]+counts[2]+counts[4]+counts[6]]];let chosen=shuffle(targets).slice(0,3);return q(`<p>A survey of <strong>${N}</strong> people asked which activities they participate in:</p><ul>${names.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>The survey found these <strong>mutually exclusive</strong> categories:</p>${table(['Participation category','People'],labels.map((x,i)=>[x,counts[i]]))}<p>Answer the following.</p>`,chosen.map(x=>x[0]),chosen.map(x=>x[1]),'Identify the disjoint regions that satisfy each phrase; sum their counts. “Both” includes people doing all three unless “only” is specified.',`<p>Each answer is the sum of the corresponding nonoverlapping regions:</p><ol>${chosen.map(([label,val])=>`<li><strong>${esc(label)}:</strong> ${val} people.</li>`).join('')}</ol><p>The eight categories total ${N}.</p>`);});
replace('sets','Complement and De Morgan',()=>{let first=P([true,false]);let A=first?'(A\\cup B)^c':'(A\\cap B)^c',ans=first?'A^c\\cap B^c':'A^c\\cup B^c';let choices=first?['A^c\\cup B^c','A^c\\cap B^c','A\\cap B','A\\cup B']:['A^c\\cap B^c','A\\cap B','A^c\\cup B^c','A\\cup B'];return mc(`Which expression equals ${math(A)}?`,choices.map(math),choices.indexOf(ans),`<p>De Morgan’s laws interchange union and intersection and complement each operand:</p>${math(`${A}=${ans}`)}.`);});
replace('sets','Survey: inclusion-exclusion',()=>{let a=R(18,35),b=R(15,32),both=R(5,Math.min(a,b)-3),none=R(6,17),N=a+b-both+none,labels=P([['library','tutoring center'],['basketball','volleyball'],['coffee','tea'],['bus','train']]);let mode=P([0,1,2]);let asks=[['Exactly one',a+b-2*both],['Neither',none],['At least one',a+b-both]][mode];return q(`Among ${N} people, ${a} use ${labels[0]}, ${b} use ${labels[1]}, and ${both} use both. How many use <strong>${asks[0].toLowerCase()}</strong>?`,[asks[0]],[asks[1]],'Apply inclusion–exclusion, then distinguish exactly one, at least one, and neither.',`<p>${math('|A\\cup B|=|A|+|B|-|A\\cap B|')} = ${a}+${b}-${both}=${a+b-both}.</p><p>Exactly one = ${a}-${both}+${b}-${both}=${a+b-2*both}; neither = ${N}-(${a+b-both})=${none}. Therefore ${asks[0].toLowerCase()} = <strong>${asks[1]}</strong>.</p>`);});
// PROBABILITY: cards, contextual events, and matching symbolic expressions.
replace('prob','Two draws without replacement',()=>{let mode=P([0,1,2,3]);let red=R(5,11),blue=R(5,11),N=red+blue;let contexts=[{text:`A standard deck of 52 cards is shuffled. Two cards are drawn without replacement. What is the probability both are hearts?`,a:13/52*12/51,formula:'\\frac{13}{52}\\cdot\\frac{12}{51}'},{text:`Two cards are drawn from a standard deck without replacement. What is the probability they have the same rank?`,a:3/51,formula:'\\frac{3}{51}'},{text:`A bag contains ${red} red and ${blue} blue marbles. Two are drawn without replacement. What is the probability both are red?`,a:red/N*(red-1)/(N-1),formula:`\\frac{${red}}{${N}}\\cdot\\frac{${red-1}}{${N-1}}`},{text:`Two cards are drawn without replacement. Given that the first is the ace of spades, what is the probability the second is a spade?`,a:12/51,formula:'\\frac{12}{51}'}];let t=contexts[mode];return q(t.text,['Probability'],[t.a],'For draws without replacement, update the number of available cards or objects after the first draw.',`${math('P='+t.formula+'\\approx '+D(t.a))}. The denominator changes after the first draw because the card or marble is not returned.`);});
add('prob','Playing cards: unions, complements and replacement',()=>{let mode=P([0,1,2,3,4]),cases=[['a heart or a king',(13+4-1)/52,'\\frac{13+4-1}{52}'],['a face card (J, Q, or K)',12/52,'\\frac{12}{52}'],['neither a heart nor a face card',(52-(13+12-3))/52,'\\frac{52-(13+12-3)}{52}'],['a red card on each of two independent draws with replacement',.25,'\\frac{26}{52}\\cdot\\frac{26}{52}'],['a heart or an even-numbered card (2, 4, 6, 8, 10)',(13+20-5)/52,'\\frac{13+20-5}{52}']];let [event,answer,formula]=cases[mode];return q(`A standard 52-card deck has four suits of 13 cards each. Face cards are J, Q, K. Find the probability of <strong>${event}</strong>.`,['Probability'],[answer],`For “or”, count the overlap only once. For two independent draws, multiply probabilities.`,`<p>${math('P='+formula+'\\approx '+D(answer))}.</p><p>Each suit has 13 cards; 12 cards are face cards; hearts contain 3 face cards and 5 even-numbered cards.</p>`);});
add('prob','Match verbal probabilities to notation',()=>{let [A,B,context]=P([['J','C','students with part-time jobs (J) and students who own cars (C)'],['S','B','students who study regularly (S) and students who use the library (B)'],['T','R','commuters who use transit (T) and commuters who ride a bicycle (R)'],['A','E','people who attend an event (A) and people who arrive early (E)']]);let p=shuffle([.15,.25,.4,.55,.65,.75]).slice(0,4),symbols=[`P(${B}\\mid ${A})`,`P(${A}\\cap ${B})`,`P(${A}\\cup ${B})`,`P(${B}^{c})`],statements=[`${p[0]*100}% of those in ${A} also belong to ${B}.`,`${p[1]*100}% belong to both ${A} and ${B}.`,`${p[2]*100}% belong to ${A} or ${B} (or both).`,`${p[3]*100}% do not belong to ${B}.`];let order=shuffle([0,1,2,3]);return q(`<p>In a study of ${context}, match each statement to the correct probability notation. The values are <strong>separate hypothetical statements</strong>; do not assume they describe one joint distribution.</p><p><strong>Events:</strong> ${A} and ${B} are defined above.</p><ol>${statements.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>`,statements.map((_,i)=>`Statement ${i+1}`),[0,1,2,3].map(i=>order.indexOf(i)),'“Among those in A” means conditional on A. “Both” means intersection; “or” means union; “not” means complement.',`<ol>${symbols.map((s,i)=>`<li>${statements[i]} ${math(s+'='+p[i].toFixed(2))}.</li>`).join('')}</ol>`,{choices:statements.map(()=>order.map(i=>math(symbols[i])))});});
replace('prob','Independent or mutually exclusive?',()=>{let kind=P([0,1,2,3]);let cases=[['A die is rolled once. A={even result}, B={result greater than 3}.',3,'P(A)=3/6, P(B)=3/6, P(A∩B)=2/6, but (3/6)(3/6)=1/4. They overlap, but are not independent.'],['One card is drawn from a standard deck. A={heart}, B={spade}.',0,'No card can be both a heart and a spade, so P(A∩B)=0. Both events have positive probability, so they are not independent.'],['Two independent fair coin tosses are made. A={first heads}, B={second heads}.',1,'P(A∩B)=1/4=P(A)P(B), so independent; both can occur, so not mutually exclusive.'],['One card is drawn. A={red}, B={heart}.',3,'P(A∩B)=13/52=1/4, but P(A)P(B)=(1/2)(1/4)=1/8; they overlap and are dependent.']];let [text,ans,why]=cases[kind];return mc(text+' Which classification is correct?',['Mutually exclusive only','Independent only','Both','Neither'],ans,why);});
// STATISTICS: rich datasets, frequency work, paired-data calculations, interpretation.
replace('stats','Population, sample and statistic',()=>{let n=R(120,480),mean=R(7,19),context=P(['weekly study hours','daily commute time','number of classes missed','monthly grocery spending']);let questions=[['Population','All university students',[`All university students`,`The ${n} surveyed students`,'The sample mean']],['Sample',`The ${n} surveyed students`,[`The ${n} surveyed students`,'All university students','The measured variable']],['Statistic',`The sample mean ${mean}`,[`The sample mean ${mean}`,'The unknown population mean','The survey group']],['Parameter','The unknown university-wide mean',['The unknown university-wide mean',`The sample mean ${mean}`,'The sample size']],['Variable',context,[context,'The surveyed group','The population mean']],['Study type','Observational study',['Observational study','Randomized experiment','Census']],['Possible sampling bias','Surveying only library visitors',['Surveying only library visitors','Random sampling across campus','Using a larger sample']]];let selected=shuffle(questions).slice(0,R(4,6)),opts=selected.map(x=>shuffle(x[2]));return q(`<p>A researcher surveys ${n} students at a university about <strong>${context}</strong>, reporting an average of ${mean}. No treatment is assigned.</p><p>Identify each of the following terms.</p>`,selected.map(x=>x[0]),selected.map((x,i)=>opts[i].indexOf(x[1])),'A population is the entire group; a sample is the observed subset; a statistic describes the sample and a parameter describes the population.',`<ol>${selected.map(x=>`<li><strong>${esc(x[0])}:</strong> ${esc(x[1])}.</li>`).join('')}</ol>`,{choices:opts});});
replace('stats','Variable type and graph choice',()=>{let cases=[['the distribution of numerical exam scores','Histogram','Numerical measurements grouped into intervals are displayed with a histogram.'],['the number of students in each major','Bar diagram','Separate bars compare distinct categories.'],['monthly sales over two years','Time-series graph','Chronological observations should be connected in time order.'],['the proportions of votes for different candidates','Pie chart','Pie charts show how categories divide a whole.'],['the relationship between hours studied and exam scores','Scatterplot','A scatterplot displays paired quantitative observations.'],['the daily temperatures recorded over 30 days','Time-series graph','Temperatures measured over time should be shown on a time-series graph.'],['the number of vehicles of each type in a parking lot','Bar diagram','Vehicle types are categorical values.']];let [context,answer,why]=P(cases),opts=shuffle(['Histogram','Bar diagram','Time-series graph','Pie chart','Scatterplot']);return mc(`Which display is most appropriate for <strong>${context}</strong>?`,opts,opts.indexOf(answer),why);});
replace('stats','Mean, median and outliers',()=>{let n=R(11,17),base=R(15,50),data=Array.from({length:n},()=>base+R(-12,18)),out=P([true,false]);if(out)data[R(0,n-1)]=base+R(65,95);let sorted=[...data].sort((a,b)=>a-b),median=n%2?sorted[(n-1)/2]:(sorted[n/2-1]+sorted[n/2])/2;return q(`A study recorded ${n} observations: <p class="dataset">${data.join(', ')}</p> Find the mean and median.`,['Mean','Median'],[avg(data),median],'Mean = sum of all observations divided by n. Sort the observations before finding the median.',`<p>${math('\\bar{x}=\\frac{\\sum x_i}{n}=\\frac{'+sum(data)+'}{'+n+'}\\approx '+D(avg(data)))}.</p><p>Ordered data: ${sorted.join(', ')}. The middle ${n%2?'observation':'two observations'} give(s) median = <strong>${median}</strong>.</p>${out?'<p>The extreme high value has a larger effect on the mean than on the median.</p>':''}`);});
replace('stats','Variance and standard deviation',()=>{let n=R(10,14),base=R(20,55),data=Array.from({length:n},()=>base+R(-15,15)),v=variance(data,true),den=n-1;return q(`The following sample of ${n} measurements was collected: <p class="dataset">${data.join(', ')}</p> Calculate the sample variance and standard deviation.`,['Variance','Standard deviation'],[v,Math.sqrt(v)],`Compute ${math('\\bar{x}=\\sum x_i/n')}, then sum the squared deviations and divide by n−1.`,`<p>${math('\\bar{x}=\\frac{'+sum(data)+'}{'+n+'}\\approx '+D(avg(data)))}.</p>${table(['Observation x','x − mean','(x − mean)²'],data.map(x=>[x,D(x-avg(data)),D((x-avg(data))**2)]))}<p>${math('\\sum(x_i-\\bar{x})^2='+D(sum(data.map(x=>(x-avg(data))**2)))+';\\quad '+'s^2'+'=\\frac{'+D(sum(data.map(x=>(x-avg(data))**2)))+'}{'+den+'}\\approx '+D(v))}.</p><p>Standard deviation = ${math('\\sqrt{'+D(v)+'}\\approx '+D(Math.sqrt(v)))}.</p>`);});
replace('stats','Build a histogram',()=>{let start=R(0,3)*10,width=P([5,10]),n=R(19,27),freq=[0,0,0,0],data=Array.from({length:n},()=>{let j=R(0,3);freq[j]++;return start+j*width+R(0,width-1)}),labels=Array.from({length:4},(_,i)=>`[${start+i*width},${start+(i+1)*width})`);return q(`<p>Travel times (minutes) for ${n} people:</p><p class="dataset">${shuffle(data).join(', ')}</p><p><strong>A.</strong> Complete the frequency table. <strong>B.</strong> Construct the histogram using the +/− controls. Both parts are graded.</p>`,['Histogram'],freq,'Count observations in each interval, including the left endpoint but not the right endpoint.',`<p>Completed frequency table:</p>${table(['Interval','Frequency'],labels.map((x,i)=>[x,freq[i]]))}<p>Check: ${freq.join('+')}=${n}. Each histogram bar has height equal to its frequency.</p>`,{diagram:{type:'bars',kind:'histogram',labels,correct:freq,max:Math.max(12,...freq)+1},tableAnswers:{headers:['Interval','Frequency'],rows:labels.map(x=>[x,null]),correct:freq.map(x=>[x])}});});
const categorical=()=>{let [context,cats]=P([['preferred exercise',['Gym','Running','Swimming','Cycling']],['usual transportation',['Bus','Car','Walking','Bicycle']],['favorite drink',['Tea','Coffee','Water','Juice']],['favorite activity',['Art','Music','Sports','Games']],['study location',['Library','Home','Café','Study room']]]),freq=Array.from({length:4},()=>R(4,10));freq[R(0,3)]+=R(2,5);return {context,cats,freq,data:shuffle(cats.flatMap((v,i)=>Array(freq[i]).fill(v)))};};
function categoricalDiagram(){let {context,cats,freq,data}=categorical(),kind=P(['bars','pie']),n=data.length,percent=freq.map(v=>100*v/n),mode=cats[freq.indexOf(Math.max(...freq))];return q(`<p>A survey of ${n} people asked about <strong>${esc(context)}</strong>. Responses:</p><p class="dataset">${data.join(' · ')}</p><p><strong>A.</strong> Complete the frequency and percentage table. <strong>B.</strong> Construct a <strong>${kind==='bars'?'bar chart':'pie chart'}</strong>. <strong>C.</strong> Identify the mode.</p>`,['Mode'],[cats.indexOf(mode)],'Count each category. Percentage = 100 × frequency / total. The mode is the category with the largest frequency.',`<p>Completed table:</p>${table(['Category','Frequency','Percentage','Sector angle'],cats.map((x,i)=>[x,freq[i],D(percent[i])+'%',D(360*freq[i]/n)+'°']))}<p>${math('\text{Percentage}=\frac{\text{frequency}}{'+n+'}\times100\%')} and ${math('\text{Angle}=\frac{\text{frequency}}{'+n+'}\times360^\circ')}.</p><p><strong>Mode:</strong> ${esc(mode)} (${Math.max(...freq)} responses).</p>`,{choices:[cats],diagram:{type:kind,kind:'bar',labels:cats,correct:kind==='bars'?freq:percent,max:Math.max(12,...freq)+1},diagramFields:true,tableAnswers:{headers:['Category','Frequency','Percentage (%)'],rows:cats.map(x=>[x,null,null]),correct:cats.map((x,i)=>[freq[i],percent[i]])}});}
