replace('stats','Plot a scatter diagram',()=>{let x=shuffle([1,2,3,4,5,6]),slope=P([-1,1]),y=x.map(v=>Math.max(0,Math.min(10,Math.round((slope===1?v:10-v)+R(-2,2))))),xb=avg(x),yb=avg(y),vx=variance(x),vy=variance(y),cv=covar(x,y),r=cv/(sd(x)*sd(y)),points=x.map((v,i)=>[v,y[i]]),context=P([['Weekly study time (hours)','Practice test score (scaled 0–10)'],['Exercise sessions per week','Resting stress rating (0–10)'],['Daily outdoor time (hours)','Mood rating (0–10)'],['Days absent','Participation score (0–10)']]);return q(`<p>A researcher records the following <strong>six paired observations</strong>:</p><p><strong>x:</strong> ${context[0]}; <strong>y:</strong> ${context[1]}.</p>${table(['Observation','x','y'],points.map((p,i)=>[i+1,p[0],p[1]]))}<p><strong>Part A:</strong> Plot all six points. <strong>Part B:</strong> Calculate the sample means, sample standard deviations, sample covariance, and Pearson correlation coefficient.</p>`,['Mean of x','Mean of y','Sample SD of x','Sample SD of y','Sample covariance','Correlation r'],[xb,yb,sd(x),sd(y),cv,r],'Plot each (x,y) pair. Use sample denominators n−1 for variance and covariance, and r=cov(x,y)/(sₓsᵧ).',`<p>Plot these coordinates: ${points.map(p=>`(${p.join(',')})`).join(', ')}.</p><p>${math('\\bar{x}='+D(xb)+',\\quad\\bar{y}='+D(yb))}.</p><p>${math('s_x=\\sqrt{\\frac{\\sum(x_i-\\bar{x})^2}{5}}='+D(sd(x))+';\\quad s_y=\\sqrt{\\frac{\\sum(y_i-\\bar{y})^2}{5}}='+D(sd(y)))}.</p><p>${math('\\operatorname{Cov}(x,y)=\\frac{\\sum(x_i-\\bar{x})(y_i-\\bar{y})}{5}='+D(cv))}.</p><p>${math('r=\\frac{\\operatorname{Cov}(x,y)}{s_xs_y}='+D(r))}.</p>${table(['x','y','x−x̄','y−ȳ','(x−x̄)(y−ȳ)'],points.map(([a,b])=>[a,b,D(a-xb),D(b-yb),D((a-xb)*(b-yb))]))}`,{diagram:{type:'scatter',correct:points},diagramFields:true});});
replace('stats','Correlation and regression',()=>{let n=6,x=[1,2,3,4,5,6],m=P([-3,-2,2,3,4]),b=R(18,48),y=x.map(v=>m*v+b+R(-3,3)),xb=avg(x),yb=avg(y),vx=variance(x),cv=covar(x,y),slope=cv/vx,intercept=yb-slope*xb,predict=R(7,10),pred=slope*predict+intercept;return q(`<p>A researcher studies the relationship between <strong>weekly training sessions (x)</strong> and <strong>performance score (y)</strong>:</p>${table(['x','y'],x.map((v,i)=>[v,y[i]]))}<p>Find the least-squares regression equation ${math('y=mx+b')} and use it to predict y when x=${predict}. Enter m, b, and the prediction separately.</p>`,['Slope m','Intercept b',`Predicted y when x=${predict}`],[slope,intercept,pred],'Compute both means, sample variance of x, and sample covariance; then m=cov(x,y)/Var(x), b=ȳ−mx̄.',`<p>${math('\\bar{x}='+D(xb)+',\\quad\\bar{y}='+D(yb))}.</p><p>${math('\\operatorname{Var}(x)='+D(vx)+',\\quad\\operatorname{Cov}(x,y)='+D(cv))}.</p><p>${math('m=\\frac{\\operatorname{Cov}(x,y)}{\\operatorname{Var}(x)}=\\frac{'+D(cv)+'}{'+D(vx)+'}\\approx '+D(slope))}.</p><p>${math('b=\\bar{y}-m\\bar{x}='+D(yb)+'-('+D(slope)+')('+D(xb)+')\\approx '+D(intercept))}.</p><p>Regression line: ${math('\\hat y='+D(slope)+'x+'+D(intercept))}. Predicted value: ${math('\\hat y('+predict+')='+D(pred))}.</p>`);});
replace('stats','Interpreting correlation',()=>{let r=P([-.94,-.78,-.57,-.38,-.14,.08,.3,.53,.76,.93]),strength=Math.abs(r)<.2?'Very weak':Math.abs(r)<.4?'Weak':Math.abs(r)<.7?'Moderate':'Strong',direction=r<0?'negative':'positive',answer=strength+' '+direction+' linear relationship';let options=shuffle(['Strong positive linear relationship','Strong negative linear relationship','Moderate positive linear relationship','Moderate negative linear relationship','Weak positive linear relationship','Weak negative linear relationship','Very weak positive linear relationship','Very weak negative linear relationship','Nonlinear relationship']);return mc(`A study reports ${math('r='+r)}. Which is the most appropriate description of the <strong>linear</strong> relationship?`,options,options.indexOf(answer),`The sign indicates direction (${direction}); ${math('|r|='+Math.abs(r))} indicates the strength (${strength.toLowerCase()}). Correlation alone cannot establish that a nonlinear relationship exists.`);});
add('stats','Estimate correlation from a scatterplot',()=>{let type=P(['strong+','strong-','moderate+','moderate-','weak','curve']),x=Array.from({length:9},(_,i)=>i+1),y=x.map(v=>{let z=type==='curve'?(v-5)**2/3+1:type==='strong+'?v+R(-1,1):type==='strong-'?10-v+R(-1,1):type==='moderate+'?3+v*.6+R(-3,3):type==='moderate-'?8-v*.6+R(-3,3):5+R(-4,4);return Math.max(0,Math.min(10,Math.round(z)))}),r=covar(x,y)/(sd(x)*sd(y)),choices=shuffle([D(r),D(-r),D(Math.max(-.99,Math.min(.99,r>0?.12:-.12))),D(Math.max(-.99,Math.min(.99,r>0?-.85:.85)))]);let unique=[...new Set(choices)];while(unique.length<4){let candidate=D(R(-95,95)/100);if(!unique.includes(candidate))unique.push(candidate);}return q(`<p>Inspect the scatterplot below. Which value is the <strong>most reasonable estimate</strong> of Pearson's correlation coefficient?</p><div class="static-scatter">${scatterSVG(x.map((v,i)=>[v,y[i]]))}</div>`,['Estimated r'],[unique.indexOf(D(r))],'Look for the direction and closeness to a straight line; a curved pattern can have a weak Pearson correlation despite a clear nonlinear relationship.',`<p>The actual coefficient from the plotted observations is ${math('r\\approx '+D(r))}.</p><p>${type==='curve'?'The points follow a curved pattern, so Pearson correlation may be near zero even though the variables are related.':'The sign comes from the overall trend; the magnitude reflects how tightly points cluster about a straight line.'}</p>`,{choices:[unique]});});
function scatterSVG(points){let dots=points.map(([x,y])=>`<circle cx="${30+x*24}" cy="${278-y*24}" r="5" fill="#155b98"/>`).join('');let lines=Array.from({length:11},(_,i)=>`<line x1="${30+i*24}" y1="38" x2="${30+i*24}" y2="278" stroke="#dbe4ee"/><line x1="30" y1="${38+i*24}" x2="270" y2="${38+i*24}" stroke="#dbe4ee"/><text x="${30+i*24}" y="296" text-anchor="middle" font-size="10">${i}</text><text x="20" y="${282-i*24}" text-anchor="end" font-size="10">${i}</text>`).join('');return `<svg viewBox="0 0 305 315" width="360" style="max-width:100%" role="img" aria-label="Scatterplot of nine paired observations">${lines}${dots}<text x="150" y="313" text-anchor="middle" font-size="12">x</text><text x="10" y="26" font-size="12">y</text></svg>`;}


// Worked-method supplements for original question types retained from Exam 3.
const methodNotes={
'Fundamental counting principle':'\\[N=n_1\\cdot n_2\\cdots n_k\\] Multiply the number of independent choices at each stage.',
'Permutations or combinations?':'\\[P(n,r)=\\frac{n!}{(n-r)!},\\qquad C(n,r)=\\frac{n!}{r!(n-r)!}\\] Use permutations for distinct positions and combinations for unordered groups.',
'Teams with restrictions':'\\[\\text{valid}=\\text{all possible}-\\text{invalid}\\] Subtract committees containing both prohibited members.',
'Committees with categories':'\\[\\text{total}=C(a,x)\\cdot C(b,y)\\] Choose members independently from each category.',
'License plates and repetition':'\\[\\text{total}=\\text{letter arrangements}\\times\\text{digit arrangements}\\] With repetition each letter position has 26 choices; without repetition use descending factors.',
'Counting method recognition':'\\[P(n,r)=\\frac{n!}{(n-r)!},\\quad C(n,r)=\\frac{n!}{r!(n-r)!}\\] Decide whether changing the order changes the outcome.',
'At least one condition':'\\[\\text{at least one}=\\text{all}-\\text{none}\\] The complement avoids counting overlapping cases separately.',
'Complement and simple events':'\\[P(A^c)=1-P(A)\\] Count outcomes outside A or subtract P(A) from 1.',
'Two-way table and conditional probability':'\\[P(B\\mid A)=\\frac{P(A\\cap B)}{P(A)},\\quad P(A\\cup B)=P(A)+P(B)-P(A\\cap B)\\] The conditional denominator is the size of the restricted row or column.',
'Law of total probability':'\\[P(A)=P(A\\mid D)P(D)+P(A\\mid D^c)P(D^c)\\] Add the mutually exclusive ways that event A can occur.',
'Bayes theorem':'\\[P(D\\mid A)=\\frac{P(A\\mid D)P(D)}{P(A)}\\] The denominator P(A) includes positive results from both groups.',
'Probability using combinations':'\\[P(E)=\\frac{\\text{favorable selections}}{\\text{all selections}},\\quad C(n,r)=\\frac{n!}{r!(n-r)!}\\] Count unordered selections in numerator and denominator.',
'Sampling bias and misleading displays':'A representative sample should be selected from the full population of interest. A graph must match the variable type and must not imply an ordering or continuity that the data do not have.',
'Temperature conversion':'\\[C=\\frac59(F-32),\\qquad F=\\frac95C+32\\] Substitute the given temperature and retain the target units.',
'Speed conversion':'\\[\\text{speed in km/h}=\\text{speed in mph}\\times1.609344\\] Divide by 1.609344 to reverse the conversion.',
'Area and volume conversion':'\\[1\\text{ ft}^2=12^2\\text{ in}^2,\\qquad1\\text{ in}^3=(2.54)^3\\text{ cm}^3\\] Square length factors for area and cube them for volume.',
'Dimensional analysis and weight':'\\[1\\text{ kg}=2.20462\\text{ lb}\\] Multiply by a conversion factor arranged to cancel the original unit.',
'Compare unit prices':'\\[\\text{unit price}=\\frac{\\text{total cost}}{\\text{quantity}}\\] Compare values in the same currency and per the same unit.',
'Currency exchange and surface pricing':'\\[\\text{USD}=\\frac{\\text{CAD}}{\\text{CAD per USD}}\\] Unit cancellation confirms whether to multiply or divide.',
'Reverse percentages and tax':'\\[\\text{original}=\\frac{\\text{final}}{1+\\text{tax rate}+\\text{tip rate}}\\] This applies when both percentages are based on the original amount.',
'Monthly budget and savings rate':'\\[\\text{savings}=\\text{income}-\\text{expenses},\\quad\\text{rate}=\\frac{\\text{savings}}{\\text{income}}\\times100\\%\\] Use consistent monthly units.',
'Inflation over multiple years':'\\[A=P(1+r_1)(1+r_2)(1+r_3)\\] Apply each change to the updated balance, not the original price.',
'Simple interest and maturity':'\\[I=Prt,\\quad A=P+I=P(1+rt)\\] Convert months into years and the percent rate into a decimal.',
'Compound growth':'\\[A=P\\left(1+\\frac rn\\right)^{nt}\\] Here n is the number of compounding periods per year.',
'Amortized loan payments':'\\[M=\\frac{Pi}{1-(1+i)^{-N}},\\quad i=\\frac{r}{12}\\] Here r is an annual decimal rate, N is the number of monthly payments.',
'Mortgage and down payment':'\\[P=\\text{house price}-\\text{down payment},\\quad M=\\frac{Pi}{1-(1+i)^{-N}}\\] Total cost adds the down payment and all monthly payments.',
'Credit card minimum payment':'\\[\\text{new balance}=\\text{old balance}\\left(1+\\frac{\\text{APR}}{12}\\right)\\] Calculate the minimum payment from the new balance, then subtract it.',
'Conceptual loan types':'A subsidized student loan generally does not accrue interest for the borrower during eligible in-school periods; an unsubsidized loan accrues interest. An amortized loan reduces principal through scheduled payments.',
'Retirement annuity':'\\[FV=d\\frac{(1+i)^N-1}{i},\\quad i=\\frac{r}{52},\\quad N=52t\\] End-of-week deposits form an ordinary annuity.'
};
for(const group of Object.values(B))for(const item of group){if(methodNotes[item.title]){const old=item.make;item.make=()=>{let d=old();d.solution=`<div class="math-method"><strong>Formula and method:</strong> ${methodNotes[item.title]}</div><p><strong>Substitution and result:</strong> ${d.solution}</p>`;return d;};}}

// INTERACTIVE VISUAL INPUTS
function drawDiagram(d,host,id){let cfg=d.diagram;if(!cfg)return;let state=d._state??(d._state=cfg.type==='venn'?[]:cfg.type==='scatter'?[]:cfg.correct.map(()=>0));let html='';if(cfg.type==='venn'){let labels=['A only','B only','A∩B only','C only','A∩C only','B∩C only','A∩B∩C','Outside all three (8)'];html='<svg class="venn-picture" viewBox="0 0 330 225" role="img" aria-label="Three intersecting sets A B and C"><rect x="5" y="5" width="320" height="215" fill="#f8fafc" stroke="#94a3b8"/><circle cx="120" cy="91" r="72" fill="none" stroke="#456b94" stroke-width="2"/><circle cx="208" cy="91" r="72" fill="none" stroke="#456b94" stroke-width="2"/><circle cx="164" cy="147" r="72" fill="none" stroke="#456b94" stroke-width="2"/><text x="68" y="29">A</text><text x="254" y="29">B</text><text x="164" y="212">C</text>'+[[92,75],[236,75],[164,55],[164,175],[113,130],[214,130],[164,105],[304,196]].map((xy,i)=>'<circle cx="'+xy[0]+'" cy="'+xy[1]+'" r="12" fill="'+(state.includes(i+1)?'#155b98':'#d9e4f0')+'" stroke="#7894b1"/><text x="'+xy[0]+'" y="'+(xy[1]+4)+'" text-anchor="middle" font-size="11" fill="'+(state.includes(i+1)?'white':'#1e293b')+'">'+(i+1)+'</text>').join('')+'</svg><div class="venn-grid">'+labels.map((v,i)=>`<button type="button" class="region ${state.includes(i+1)?'selected':''}" data-diagram="${i+1}" aria-pressed="${state.includes(i+1)}">${esc(v)}</button>`).join('')+'</div><p class="muted">Select the region(s) to shade. Each tile represents a distinct Venn region.</p>';}else if(cfg.type==='bars'){let max=cfg.max||12;html=`<div class="chart-editor ${cfg.kind}">`+cfg.labels.map((label,i)=>`<div class="bar-col"><div class="bar-plot"><div class="bar-fill" style="height:${state[i]/max*100}%"></div></div><strong>${state[i]}</strong><div class="bar-label">${esc(label)}</div><div class="bar-controls"><button type="button" data-diagram="minus:${i}" aria-label="Decrease ${esc(label)}">−</button><button type="button" data-diagram="plus:${i}" aria-label="Increase ${esc(label)}">+</button></div></div>`).join('')+'</div><p class="muted">Use + and − to change each bar height.</p>';}else if(cfg.type==='pie'){let total=state.reduce((a,b)=>a+b,0);let start=0;let colors=['#2c659a','#e3a346','#38a27c','#8b69ae'];let stops=state.map((v,i)=>{let old=start;start+=v;return `${colors[i]} ${old}% ${start}%`;});html=`<div class="pie-work"><div class="pie-preview" style="background:conic-gradient(${stops.join(',')}${total<100?`,#e5eaf1 ${total}% 100%`:''})"></div><div>`+cfg.labels.map((v,i)=>`<label class="pie-input"><span style="color:${colors[i]}">●</span> ${esc(v)} <input type="number" min="0" max="100" step="0.01" value="${state[i]}" data-diagram="pie:${i}"> %</label>`).join('')+`<p>Total: <strong>${D(total)}%</strong></p></div></div>`;}else if(cfg.type==='scatter'){let circles=[];for(let y=10;y>=0;y--)for(let x=0;x<=10;x++){let selected=state.some(p=>p[0]===x&&p[1]===y);circles.push(`<circle data-diagram="point:${x}:${y}" cx="${32+x*25}" cy="${275-y*25}" r="${selected?7:4}" fill="${selected?'#1b6ca7':'#cbd5e1'}" class="scatter-dot"/>`);}let lines=[];for(let i=0;i<=10;i++){lines.push(`<line x1="${32+i*25}" y1="25" x2="${32+i*25}" y2="275" stroke="#e1e7f0"/>`,`<line x1="32" y1="${25+i*25}" x2="282" y2="${25+i*25}" stroke="#e1e7f0"/>`);}html=`<svg class="scatter-editor" viewBox="0 0 310 310" role="group" aria-label="Click integer coordinates on the scatter plot">${lines.join('')}<line x1="32" y1="275" x2="282" y2="275" stroke="#334155" stroke-width="2"/><line x1="32" y1="25" x2="32" y2="275" stroke="#334155" stroke-width="2"/>${Array.from({length:11},(_,i)=>`<text x="${32+i*25}" y="293" text-anchor="middle" font-size="10">${i}</text><text x="24" y="${279-i*25}" text-anchor="end" font-size="10">${i}</text>`).join('')}${circles.join('')}</svg><p class="muted">Selected: ${state.map(p=>`(${p.join(',')})`).join(', ')||'none'}</p>`;}host.innerHTML=html;host.querySelectorAll('[data-diagram]').forEach(el=>{let action=el.dataset.diagram;let fn=()=>{if(cfg.type==='venn'){let n=Number(action);d._state=state.includes(n)?state.filter(v=>v!==n):[...state,n];}else if(cfg.type==='bars'){let [op,i]=action.split(':');d._state=[...state];d._state[+i]=Math.max(0,Math.min(cfg.max,d._state[+i]+(op==='plus'?1:-1)));}else if(cfg.type==='pie'){let i=+action.split(':')[1];d._state=[...state];d._state[i]=Number(el.value)||0;}else{let [,x,y]=action.split(':').map(Number);let found=state.some(p=>p[0]===x&&p[1]===y);d._state=found?state.filter(p=>p[0]!==x||p[1]!==y):[...state,[x,y]];}drawDiagram(d,host,id);};if(cfg.type==='pie')el.addEventListener('change',fn);else el.addEventListener('click',fn);});}
function tableUI(d,prefix){if(!d.tableAnswers)return '';let t=d.tableAnswers;return `<div class="table-work"><strong>Complete the table</strong><table class="data-table"><thead><tr>${t.headers.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${t.rows.map((r,i)=>`<tr>${r.map((v,j)=>v===null?`<td><input class="table-entry" id="${prefix}-table-${i}-${j}" type="number" step="any" aria-label="${esc(t.headers[j])}, row ${i+1}" placeholder="?" /></td>`:`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table><p class="muted small">Enter all missing values, then check your answer. Each cell receives feedback.</p></div>`;}
function tableValues(d,prefix){return d.tableAnswers?d.tableAnswers.rows.flatMap((r,i)=>r.flatMap((v,j)=>v===null?[document.getElementById(`${prefix}-table-${i}-${j}`)?.value??'']:[])):[];}
function tableCheck(d,vals){if(!d.tableAnswers)return true;let expected=d.tableAnswers.correct.flat();return vals.length===expected.length&&vals.every((v,i)=>v!==''&&Math.abs(Number(v)-expected[i])<=Math.max(.055,Math.abs(expected[i])*.000001));}
function markTable(d,prefix){if(!d.tableAnswers)return {correct:true,message:''};let expected=d.tableAnswers.correct.flat(),vals=tableValues(d,prefix),correct=0;let inputs=[...document.querySelectorAll(`[id^="${prefix}-table-"]`)];inputs.forEach((el,i)=>{let ok=vals[i]!==''&&Math.abs(Number(vals[i])-expected[i])<=Math.max(.055,Math.abs(expected[i])*.000001);el.classList.toggle('cell-correct',ok);el.classList.toggle('cell-incorrect',!ok);el.setAttribute('aria-invalid',String(!ok));if(ok)correct++;});return {correct:correct===expected.length,message:`Table: ${correct} of ${expected.length} cells correct.`};}
function answerUI(d,prefix){if(d.diagram)return `${tableUI(d,prefix)}<div class="diagram-host" id="${prefix}-diagram"></div>${d.diagramFields?`<div class="answers">${d.fields.map((f,j)=>`<label>${esc(f)}<input id="${prefix}-${j}" type="number" step="any" placeholder="Your answer"></label>`).join('')}</div>`:''}`;if(d.multiSelect)return `<div class="multi-answers">${d.multiSelect.options.map((v,i)=>`<label><input type="checkbox" id="${prefix}-${i}" value="${v}"> ${v}</label>`).join('')}</div>`;return `<div class="answers">${d.fields.map((f,j)=>`<label>${esc(f)}${d.choices?`<select id="${prefix}-${j}"><option value="">Select an answer</option>${d.choices[j].map((v,k)=>`<option value="${k}">${esc(v)}</option>`).join('')}</select>`:`<input id="${prefix}-${j}" type="number" step="any" placeholder="Your answer" inputmode="decimal">`}</label>`).join('')}</div>`;}
function values(d,prefix){if(d.diagram)return d.diagramFields?{diagram:d._state||[],numbers:d.fields.map((_,i)=>document.getElementById(`${prefix}-${i}`).value),table:tableValues(d,prefix)}:d.tableAnswers?{diagram:d._state||[],table:tableValues(d,prefix)}:d._state||[];if(d.multiSelect)return [...document.querySelectorAll(`[id^="${prefix}-"]:checked`)].map(x=>Number(x.value));return d.fields.map((_,i)=>document.getElementById(`${prefix}-${i}`).value);}
function check(d,vals){if(d.diagram){let c=d.diagram.correct;if(d.tableAnswers&&!tableCheck(d,vals.table))return false;let chart=vals.diagram??vals;if(d.diagramFields){let numbers=vals.numbers,points=chart;return (d.diagram.type==='scatter'?points.length===c.length&&c.every(p=>points.some(v=>v[0]===p[0]&&v[1]===p[1])):points.length===c.length&&points.every((v,i)=>Math.abs(v-c[i])<=(d.diagram.type==='pie'?.055:0)))&&numbers.every((v,i)=>v!==''&&(d.choices?Number(v)===d.answers[i]:Math.abs(Number(v)-d.answers[i])<=Math.max(.0051,Math.abs(d.answers[i])*.000001)));}if(d.diagram.type==='scatter')return chart.length===c.length&&c.every(p=>chart.some(v=>v[0]===p[0]&&v[1]===p[1]));if(d.diagram.type==='venn')return chart.length===c.length&&c.every(x=>chart.includes(x));return chart.length===c.length&&chart.every((v,i)=>Math.abs(v-c[i])<=(d.diagram.type==='pie'?.055:0));}if(d.multiSelect)return vals.length===d.multiSelect.correct.length&&d.multiSelect.correct.every(v=>vals.includes(v));return vals.every((v,i)=>v!==''&&(d.choices?Number(v)===d.answers[i]:Math.abs(Number(v)-d.answers[i])<=Math.max(.0051,Math.abs(d.answers[i])*.000001)));}
function solution(d){return `<div class="details"><strong>Worked solution</strong><p>${d.solution}</p></div>`;}
let active=null,instances=[];
function nav(){document.getElementById('topics').innerHTML=sections.map(([id,name,desc])=>`<button type="button" class="topic ${active===id?'active':''}" data-topic="${id}">${name}<span>${desc}</span></button>`).join('');document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>openSection(b.dataset.topic));}
function openSection(id){active=id;nav();instances=B[id].map(item=>({item,data:item.make()}));document.getElementById('intro').hidden=true;document.getElementById('questions').innerHTML=`<h2>${sections.find(s=>s[0]===id)[1]} · ${instances.length} question types</h2><p class="muted">Practice each type independently. New Version changes the context, numbers, or assessed method where applicable.</p>`+instances.map((_,i)=>`<article class="card" id="card-${i}"></article>`).join('');instances.forEach((_,i)=>renderCard(i));}
function renderCard(i){let it=instances[i],d=it.data,pre=`pr-${i}`,el=document.getElementById(`card-${i}`);el.innerHTML=`<h3>${i+1}. ${esc(it.item.title)}</h3><div class="prompt">${d.text}</div>${answerUI(d,pre)}<div class="actions"><button type="button" class="primary" data-act="check">Check Answer</button><button type="button" data-act="hint">Hint</button><button type="button" data-act="solution">Show Solution</button><button type="button" data-act="new">Generate New</button></div><div class="feedback-slot" aria-live="polite"></div><div class="details-slot"></div>`;if(d.diagram)drawDiagram(d,document.getElementById(pre+'-diagram'),pre);el.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>{let a=b.dataset.act,feed=el.querySelector('.feedback-slot'),details=el.querySelector('.details-slot');if(a==='new'){it.data=it.item.make();renderCard(i);return;}if(a==='hint'){details.innerHTML=`<div class="details"><strong>Hint</strong><p>${d.hint}</p></div>`;tex(details);return;}if(a==='solution'){details.innerHTML=solution(d);tex(details);return;}let v=values(d,pre),ok=check(d,v);let t=markTable(d,pre);feed.innerHTML=`<div class="feedback ${ok?'good':'bad'}">${ok?'✓ Correct!':'Not yet. Try again, request a hint, or view the solution.'}${t.message?' '+t.message:''}</div>`;});tex(el);}
if(document.getElementById('topics'))nav();
